import CryptoKit
import Foundation
import XCTest

@testable import OpenMedKit

/// Replays `tests/fixtures/parity/receipt_verification_v1.json`, generated by
/// Python's `AuditReport.sign()` and `verify()` with published test-only HMAC
/// material, through ``OpenMedReceiptVerifier``.
final class ReceiptVerificationParityTests: XCTestCase {
    /// Synthetic planted material: it must never reach a description.
    private static let sentinel = "Quorble Zyxwick MRN-PLANTED-0042"

    /// The reason each case must report; Python records only the verdict.
    private static let reasons: [String: OpenMedReceiptVerification.Reason] = [
        "signed_baseline": .valid,
        "unsigned": .signatureMismatch,
        "tampered_offset": .hashMismatch,
        "tampered_label": .hashMismatch,
        "tampered_action": .hashMismatch,
        "tampered_signature_byte": .signatureMismatch,
        "unknown_algorithm": .unsupportedAlgorithm,
        "legacy_span_order": .valid,
        "non_ascii_keys_and_values": .valid,
        "float_edge_cases": .valid,
    ]

    func testEveryVectorVerifiesAsPythonDoesWithIdenticalCanonicalBytes() throws {
        let fixture = try loadFixture()
        XCTAssertEqual(string(fixture, "schema"), "openmed.receipt_verification_vectors")
        XCTAssertEqual(member(fixture, "signature_algorithm").flatMap(string), OpenMedReceiptVerifier.signatureAlgorithm)
        let verifier = try XCTUnwrap(OpenMedReceiptVerifier(key: try testKey(fixture)))
        let material = try testMaterial(fixture)
        let cases = try XCTUnwrap(array(member(fixture, "cases")))
        XCTAssertEqual(Set(cases.compactMap { member($0, "id").flatMap(string) }), Set(Self.reasons.keys))

        for entry in cases {
            let id = try XCTUnwrap(member(entry, "id").flatMap(string))
            let report = ReceiptJSON.encode(try XCTUnwrap(member(entry, "report"), id))
            let expected = try XCTUnwrap(member(entry, "expected"), id)

            let verification = verifier.verify(report)
            XCTAssertEqual(verification.reason, Self.reasons[id], id)
            XCTAssertEqual(verification.isValid, boolean(expected, "verifies"), id)
            XCTAssertEqual(verification.reproHashMatches, boolean(expected, "repro_hash_matches"), id)
            XCTAssertEqual(verification.matchedSpanOrder?.rawValue, member(expected, "matched_span_order").flatMap(string), id)

            let produced = try XCTUnwrap(OpenMedReceiptVerifier.candidates(report), id)
            let recorded = try XCTUnwrap(array(member(entry, "candidates")), id)
            XCTAssertFalse(recorded.isEmpty, id)
            for candidate in recorded {
                let order = try XCTUnwrap(member(candidate, "span_order").flatMap(string), id)
                let actual = try XCTUnwrap(produced.first { $0.spanOrder.rawValue == order }, "\(id) \(order)")
                XCTAssertEqual(actual.reproPayload, try base64(candidate, "repro_payload_b64"), "\(id) \(order)")
                XCTAssertEqual(actual.reproHash, member(candidate, "expected_repro_hash").flatMap(string), "\(id) \(order)")
                XCTAssertEqual(actual.signingPayload, try base64(candidate, "signing_payload_b64"), "\(id) \(order)")
                let mac = HMAC<SHA256>.authenticationCode(for: actual.signingPayload, using: SymmetricKey(data: material))
                XCTAssertEqual(hex(Data(mac)), member(candidate, "expected_hmac").flatMap(string), "\(id) \(order)")
            }
        }
    }

    func testVerificationIgnoresInputWhitespaceButNotTheKey() throws {
        let fixture = try loadFixture()
        let baseline = try report(named: "signed_baseline", in: fixture)
        let verifier = try XCTUnwrap(OpenMedReceiptVerifier(key: try testKey(fixture)))
        let padded = " \n\t" + String(decoding: ReceiptJSON.encode(baseline), as: UTF8.self) + "\r\n "

        XCTAssertEqual(verifier.verify(json: padded).reason, .valid)
        let other = try XCTUnwrap(OpenMedReceiptVerifier(key: SymmetricKey(data: Data(Self.sentinel.utf8))))
        let wrongKey = other.verify(ReceiptJSON.encode(baseline))
        XCTAssertEqual(wrongKey.reason, .signatureMismatch)
        XCTAssertTrue(wrongKey.reproHashMatches)
        XCTAssertNil(wrongKey.matchedSpanOrder)
    }

    func testSignatureValuesAndAlgorithmsAreCheckedLikePython() throws {
        let fixture = try loadFixture()
        let verifier = try XCTUnwrap(OpenMedReceiptVerifier(key: try testKey(fixture)))
        let baseline = try report(named: "signed_baseline", in: fixture)
        guard case .object(let fields)? = member(baseline, "signature"),
            case .string(let value)? = ReceiptJSON.member("value", in: fields)
        else { return XCTFail("signature") }

        func verify(signature: ReceiptJSON?) -> OpenMedReceiptVerification.Reason {
            verifier.verify(ReceiptJSON.encode(replacing("signature", with: signature, in: baseline))).reason
        }
        func signature(_ entries: [(String, ReceiptJSON)]) -> ReceiptJSON {
            .object(entries.map { ReceiptJSON.Member(key: $0.0, value: $0.1) })
        }
        let algorithm = ReceiptJSON.string("HMAC-SHA256")
        // Python compares the hex digest as a string, so case and length matter.
        XCTAssertEqual(verify(signature: signature([("algorithm", algorithm), ("value", .string(value.uppercased()))])), .signatureMismatch)
        XCTAssertEqual(verify(signature: signature([("algorithm", algorithm), ("value", .string(String(value.dropLast())))])), .signatureMismatch)
        XCTAssertEqual(verify(signature: signature([("algorithm", algorithm), ("value", .string("zz" + value.dropFirst(2)))])), .signatureMismatch)
        XCTAssertEqual(verify(signature: signature([("algorithm", algorithm), ("value", .string(value))])), .valid)
        XCTAssertEqual(verify(signature: signature([("algorithm", .string("hmac-sha256")), ("value", .string(value))])), .unsupportedAlgorithm)
        XCTAssertEqual(verify(signature: signature([("value", .string(value))])), .unsupportedAlgorithm)
        XCTAssertEqual(verify(signature: signature([("algorithm", .null), ("value", .string(value))])), .unsupportedAlgorithm)
        XCTAssertEqual(verify(signature: .null), .signatureMismatch)
        XCTAssertEqual(verify(signature: nil), .signatureMismatch)
        XCTAssertEqual(verify(signature: signature([("algorithm", algorithm), ("value", .integer("7"))])), .malformed)
        XCTAssertEqual(verify(signature: signature([("algorithm", algorithm)])), .malformed)
        XCTAssertEqual(verify(signature: .string(value)), .malformed)
    }

    func testMalformedInputIsRejectedWithoutEchoingIt() throws {
        let fixture = try loadFixture()
        let verifier = try XCTUnwrap(OpenMedReceiptVerifier(key: try testKey(fixture)))
        let baseline = try report(named: "signed_baseline", in: fixture)
        let secret = Self.sentinel
        var inputs: [Data] = [
            Data(),
            Data("{\"note\": \"\(secret)\"".utf8),
            Data("[\"\(secret)\"]".utf8),
            Data("\"\(secret)\"".utf8),
            Data("{\"note\": NaN}".utf8),
            Data("{\"note\": 1e400}".utf8),
            Data("{\"note\": \"\\ud800\"}".utf8),
            Data("{\"note\": \"\u{1}\"}".utf8),
            Data("{\"note\": 01}".utf8),
            Data("{\"note\": \"\(secret)\"} trailing".utf8),
            Data([0x7B, 0x22, 0xFF, 0x22, 0x3A, 0x31, 0x7D]),
            Data(String(repeating: "[", count: 100).utf8),
            Data(count: OpenMedReceiptVerifier.maximumReportBytes + 1),
        ]
        inputs.append(ReceiptJSON.encode(replacing("spans", with: nil, in: baseline)))
        inputs.append(ReceiptJSON.encode(replacing("spans", with: .string(secret), in: baseline)))
        inputs.append(ReceiptJSON.encode(replacing("repro_hash", with: nil, in: baseline)))
        inputs.append(ReceiptJSON.encode(replacing("repro_hash", with: .integer("1"), in: baseline)))
        inputs.append(ReceiptJSON.encode(replacing("spans", with: .array([.object([ReceiptJSON.Member(key: "start", value: .double(8))])]), in: baseline)))
        let canonical = String(decoding: ReceiptJSON.encode(baseline), as: UTF8.self)
        inputs.append(Data(("{\"policy\":\"\(secret)\"," + canonical.dropFirst()).utf8))

        for (index, input) in inputs.enumerated() {
            let verification = verifier.verify(input)
            XCTAssertEqual(verification.reason, .malformed, "input \(index)")
            XCTAssertNil(verification.matchedSpanOrder, "input \(index)")
            XCTAssertFalse(verification.reproHashMatches, "input \(index)")
            for text in [String(describing: verification), String(reflecting: verification)] {
                XCTAssertFalse(text.contains(secret), "input \(index)")
                XCTAssertFalse(text.contains("Quorble"), "input \(index)")
            }
        }
    }

    func testTheKeyNeverAppearsInDescriptions() throws {
        let verifier = try XCTUnwrap(OpenMedReceiptVerifier(key: SymmetricKey(data: Data(Self.sentinel.utf8))))
        let result = verifier.verify(Data("{}".utf8))
        var dumped = ""
        dump(verifier, to: &dumped)
        dump(result, to: &dumped)

        let descriptions = [
            String(describing: verifier), String(reflecting: verifier), "\(verifier)", dumped,
            String(describing: result), String(reflecting: result),
        ]
        for text in descriptions {
            XCTAssertFalse(text.contains(Self.sentinel))
            XCTAssertFalse(text.contains("Quorble"))
            XCTAssertFalse(text.contains(hex(Data(Self.sentinel.utf8))))
        }
        XCTAssertTrue(Mirror(reflecting: verifier).children.isEmpty)
        XCTAssertEqual(String(describing: verifier), "OpenMedReceiptVerifier(algorithm: HMAC-SHA256)")
        XCTAssertEqual(String(describing: result), "OpenMedReceiptVerification(reason: malformed, span_order: none)")
    }

    func testEmptyKeysAreRefused() {
        XCTAssertNil(OpenMedReceiptVerifier(key: SymmetricKey(data: Data())))
        XCTAssertNotNil(OpenMedReceiptVerifier(key: SymmetricKey(size: .bits256)))
        XCTAssertEqual(
            OpenMedReceiptVerification.Reason.allCases.map(\.rawValue),
            ["valid", "hash_mismatch", "signature_mismatch", "unsupported_algorithm", "malformed"])
    }

    // MARK: - Canonical JSON

