    func testObjectsSortByScalarValueAndEscapeLikePython() throws {
        let input = #"""
            {"z": 1, "Z": 2, "\u00e9": "e-acute", "e\u0301": "e-combining", "Ａ": "fullwidth",
             "😀": "\ud83e\uddea", "a\/b": "slash \" quote \\ backslash",
             "ctl": "\u0000\u0001\b\t\n\f\r\u001f\u007f",
             "num": [0, -0, 12345678901234567890, -7, 1.0, 1E16, 1e-7],
             "nested": {"b": null, "a": [true, false]}}
            """#
        // Python: json.dumps(value, ensure_ascii=True, separators=(",", ":"),
        // sort_keys=True, allow_nan=False) of the same document.
        let expected = #"""
            {"Z":2,"a/b":"slash \" quote \\ backslash","ctl":"\u0000\u0001\b\t\n\f\r\u001f\u007f","e\u0301":"e-combining","nested":{"a":[true,false],"b":null},"num":[0,0,12345678901234567890,-7,1.0,1e+16,1e-07],"z":1,"\u00e9":"e-acute","\uff21":"fullwidth","\ud83d\ude00":"\ud83e\uddea"}
            """#

        let value = try XCTUnwrap(ReceiptJSON.parse(Data(input.utf8)))

        XCTAssertEqual(String(decoding: ReceiptJSON.encode(value), as: UTF8.self), expected)
        XCTAssertNil(ReceiptJSON.parse(Data(#"{"a": 1, "a": 2}"#.utf8)))
        XCTAssertNil(ReceiptJSON.parse(Data(#"{"note": "\udc00"}"#.utf8)))
        XCTAssertNil(ReceiptJSON.parse(Data(#"{"note": "\x"}"#.utf8)))
        XCTAssertNil(ReceiptJSON.parse(Data(#"{"note": 1.}"#.utf8)))
        XCTAssertNil(ReceiptJSON.parse(Data(#"{"note": -}"#.utf8)))
        XCTAssertNil(ReceiptJSON.parse(Data(#"{"note": Infinity}"#.utf8)))
    }

    // MARK: - Helpers

    private func loadFixture() throws -> ReceiptJSON {
        var root = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { root.deleteLastPathComponent() }
        let data = try Data(contentsOf: root.appending(path: "tests/fixtures/parity/receipt_verification_v1.json"))
        return try XCTUnwrap(ReceiptJSON.parse(data))
    }

    private func testMaterial(_ fixture: ReceiptJSON) throws -> Data {
        let key = try XCTUnwrap(array(member(fixture, "test_keys"))?.first)
        XCTAssertEqual(boolean(key, "test_only"), true)
        XCTAssertEqual(string(key, "encoding"), "utf-8")
        return Data(try XCTUnwrap(string(key, "material")).utf8)
    }

    private func testKey(_ fixture: ReceiptJSON) throws -> SymmetricKey {
        SymmetricKey(data: try testMaterial(fixture))
    }

    private func report(named id: String, in fixture: ReceiptJSON) throws -> ReceiptJSON {
        let cases = try XCTUnwrap(array(member(fixture, "cases")))
        let entry = try XCTUnwrap(cases.first { member($0, "id").flatMap(string) == id })
        return try XCTUnwrap(member(entry, "report"))
    }

    private func replacing(_ key: String, with value: ReceiptJSON?, in object: ReceiptJSON) -> ReceiptJSON {
        guard case .object(let members) = object else { return object }
        var result = members.filter { !ReceiptJSON.sameKey($0.key, key) }
        if let value { result.append(ReceiptJSON.Member(key: key, value: value)) }
        return .object(result)
    }

    private func member(_ value: ReceiptJSON?, _ key: String) -> ReceiptJSON? {
        guard case .object(let members)? = value else { return nil }
        return ReceiptJSON.member(key, in: members)
    }

    private func array(_ value: ReceiptJSON?) -> [ReceiptJSON]? {
        guard case .array(let values)? = value else { return nil }
        return values
    }

    private func string(_ value: ReceiptJSON) -> String? {
        guard case .string(let text) = value else { return nil }
        return text
    }

    private func string(_ object: ReceiptJSON, _ key: String) -> String? {
        member(object, key).flatMap(string)
    }

    private func boolean(_ object: ReceiptJSON, _ key: String) -> Bool? {
        guard case .boolean(let flag)? = member(object, key) else { return nil }
        return flag
    }

    private func base64(_ object: ReceiptJSON, _ key: String) throws -> Data {
        try XCTUnwrap(string(object, key).flatMap { Data(base64Encoded: $0) }, key)
    }

    private func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }
}
